// =====================================================================
// 0. Deterministic PRNG (seed 42 for all procedural geometry/particles)
// =====================================================================
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const SIM_SEED = 42;
const rng = mulberry32(SIM_SEED);          // used only while precomputing at startup, in fixed order
function rr(a, b) { return a + (b - a) * rng(); }

const DURATION = 40;
const TAU = Math.PI * 2;

// ---------- colour & math helpers ----------
// r128 performs no colour management: convert sRGB hex to linear once.
function lin8(c) { c /= 255; return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); }
function sc(hex) { return new THREE.Color().setRGB(lin8((hex >> 16) & 255), lin8((hex >> 8) & 255), lin8(hex & 255)); }
function clamp(x, a, b) { return x < a ? a : (x > b ? b : x); }
function smoothstep(a, b, x) { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); }
function lerpN(a, b, t) { return a + (b - a) * t; }
function v3(x, y, z) { return new THREE.Vector3(x, y, z); }

// ---------- monotone cubic Hermite (Fritsch-Carlson / PCHIP) on knots 0..n-1 ----------
function makePchip(ys) {
  const n = ys.length;
  const del = new Array(n - 1);
  for (let k = 0; k < n - 1; k++) del[k] = ys[k + 1] - ys[k];
  const m = new Array(n).fill(0);
  for (let k = 1; k < n - 1; k++) {
    const d0 = del[k - 1], d1 = del[k];
    m[k] = (d0 * d1 <= 0) ? 0 : 2 / (1 / d0 + 1 / d1);   // equal knot spacing
  }
  // one-sided three-point end slopes, shape preserving
  let m0 = (3 * del[0] - del[1]) / 2;
  if (Math.sign(m0) !== Math.sign(del[0])) m0 = 0;
  else if (Math.sign(del[0]) !== Math.sign(del[1]) && Math.abs(m0) > Math.abs(3 * del[0])) m0 = 3 * del[0];
  m[0] = m0;
  let mn = (3 * del[n - 2] - del[n - 3]) / 2;
  if (Math.sign(mn) !== Math.sign(del[n - 2])) mn = 0;
  else if (Math.sign(del[n - 2]) !== Math.sign(del[n - 3]) && Math.abs(mn) > Math.abs(3 * del[n - 2])) mn = 3 * del[n - 2];
  m[n - 1] = mn;
  const seg = (t) => {
    t = clamp(t, 0, n - 1);
    let k = Math.floor(t); if (k >= n - 1) k = n - 2;
    return [k, t - k];
  };
  return {
    ev(t) {
      const [k, x] = seg(t);
      const x2 = x * x, x3 = x2 * x;
      return (2 * x3 - 3 * x2 + 1) * ys[k] + (x3 - 2 * x2 + x) * m[k]
           + (-2 * x3 + 3 * x2) * ys[k + 1] + (x3 - x2) * m[k + 1];
    },
    d1(t) {                                   // first derivative (per second)
      const [k, x] = seg(t);
      const x2 = x * x;
      return (6 * x2 - 6 * x) * ys[k] + (3 * x2 - 4 * x + 1) * m[k]
           + (-6 * x2 + 6 * x) * ys[k + 1] + (3 * x2 - 2 * x) * m[k + 1];
    },
    d2(t) {                                   // second derivative (per second^2)
      const [k, x] = seg(t);
      return (12 * x - 6) * ys[k] + (6 * x - 4) * m[k]
           + (-12 * x + 6) * ys[k + 1] + (6 * x - 2) * m[k + 1];
    }
