// =====================================================================
// 1. Circuit: centreline, arc-length LUT, trackside geometry
// =====================================================================
const CP_PTS = [[0, 0, 0], [200, 0, 0], [320, 5, 60], [340, 12, 180], [260, 20, 260], [120, 15, 240],
                [60, 8, 320], [-80, 4, 340], [-200, 0, 260], [-240, 0, 120], [-160, 0, 40], [-80, 0, 0]];
const curve = new THREE.CatmullRomCurve3(CP_PTS.map(p => v3(p[0], p[1], p[2])), true, 'centripetal');
curve.arcLengthDivisions = 8000;
const L = curve.getLength();              // closed lap length (~1551.65 m)
const NL = 4000;                          // arc-length LUT samples (~0.39 m apart)
const DS = L / NL;
const LP = new Float64Array(NL * 3), LT = new Float64Array(NL * 3), LN = new Float64Array(NL * 3), LK = new Float64Array(NL);
(function buildLUT() {
  const P = v3(0, 0, 0), Tg = v3(0, 0, 0);
  for (let i = 0; i < NL; i++) {
    curve.getPointAt(i / NL, P);
    curve.getTangentAt(i / NL, Tg);
    LP[3 * i] = P.x; LP[3 * i + 1] = P.y; LP[3 * i + 2] = P.z;
    LT[3 * i] = Tg.x; LT[3 * i + 1] = Tg.y; LT[3 * i + 2] = Tg.z;
    const hl = Math.hypot(Tg.x, Tg.z) || 1;
    LN[3 * i] = -Tg.z / hl; LN[3 * i + 1] = 0; LN[3 * i + 2] = Tg.x / hl;   // n = normalize(T x up)
  }
  for (let i = 0; i < NL; i++) {
    const ip = (i - 1 + NL) % NL, inx = (i + 1) % NL;
    const dx = (LT[3 * inx] - LT[3 * ip]) / (2 * DS), dz = (LT[3 * inx + 2] - LT[3 * ip + 2]) / (2 * DS);
    LK[i] = dx * LN[3 * i] + dz * LN[3 * i + 2];   // signed curvature, >0 = corner turning right (+n)
  }
})();

// Centreline frame at arc-length s (wraps modulo L): position p, unit tangent t, right normal n, curvature k
function trk(s) {
  let u = s % L; if (u < 0) u += L;
  const f = u / DS;
  let i0 = Math.floor(f); const w = f - i0;
  i0 %= NL;
  const i1 = (i0 + 1) % NL;
  const a = 3 * i0, b = 3 * i1;
  const p = [LP[a] + (LP[b] - LP[a]) * w, LP[a + 1] + (LP[b + 1] - LP[a + 1]) * w, LP[a + 2] + (LP[b + 2] - LP[a + 2]) * w];
  let tx = LT[a] + (LT[b] - LT[a]) * w, ty = LT[a + 1] + (LT[b + 1] - LT[a + 1]) * w, tz = LT[a + 2] + (LT[b + 2] - LT[a + 2]) * w;
  const tl = Math.hypot(tx, ty, tz) || 1; tx /= tl; ty /= tl; tz /= tl;
  const hl = Math.hypot(tx, tz) || 1;
