// Rigid frame at C(s) + d*n(s): X = tangent, Y = n x T (up), Z = n (right of travel). Returns Matrix4.
function trackFrame(s, d, extraLift) {
  const k = trk(s), T = k.t, N = k.n;
  const U = [-N[2] * T[1], N[2] * T[0] - N[0] * T[2], N[0] * T[1]];
  const M = new THREE.Matrix4();
  M.makeBasis(v3(T[0], T[1], T[2]), v3(U[0], U[1], U[2]), v3(N[0], N[1], N[2]));
  M.setPosition(k.p[0] + N[0] * d, k.p[1] + N[1] * d + (extraLift || 0), k.p[2] + N[2] * d);
  return M;
}

// Floodlight masts: ~every 70 m, alternating sides
const NMAST = 22;
const MAST_S = [];
for (let k = 0; k < NMAST; k++) MAST_S.push((k + 0.5) * L / NMAST);
// Baked floodlight pool intensity on the road (0..1) at arc s, lateral lat
function poolAt(s, lat) {
  let I = 0;
  for (let k = 0; k < NMAST; k++) {
    let ds = s - MAST_S[k];
    ds -= L * Math.round(ds / L);
    I += Math.exp(-(ds * ds) / (2 * 17 * 17));
  }
  return (1 - Math.exp(-1.6 * I)) * Math.exp(-(lat * lat) / (2 * 9 * 9));
}

// Generic cross-section strip swept along the centreline.
// profile: [[lateral, heightAboveCentreline, u], ...]; spans arc sA..sB in nSeg steps.
function strip(profile, sA, sB, nSeg, opt) {
  opt = opt || {};
  const M = profile.length;
  const P = [], UV = [], CL = [], IDX = [];
  for (let i = 0; i <= nSeg; i++) {
    const s = sA + (sB - sA) * i / nSeg;
    const k = trk(s);
    for (let j = 0; j < M; j++) {
      const pr = profile[j], lat = pr[0], h = pr[1];
      P.push(k.p[0] + k.n[0] * lat, k.p[1] + h, k.p[2] + k.n[2] * lat);
      UV.push(pr[2] !== undefined ? pr[2] : j / (M - 1), (s - sA) / (opt.uvScale || 10));
      if (opt.col) { const c = opt.col(s, lat); CL.push(c[0], c[1], c[2]); }
    }
  }
  for (let i = 0; i < nSeg; i++) {
    for (let j = 0; j < M - 1; j++) {
      const a = i * M + j, b = a + 1, c = a + M, d = c + 1;
      IDX.push(a, b, c, b, d, c);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(UV, 2));
  if (opt.col) g.setAttribute('color', new THREE.Float32BufferAttribute(CL, 3));
  g.setIndex(IDX);
  g.computeVertexNormals();
  const mesh = new THREE.Mesh(g, opt.mat);
  mesh.castShadow = false;
  mesh.receiveShadow = !!opt.recv;
  return mesh;
}

// Red-and-white kerbs on the corners (non-indexed so each stripe keeps a flat colour)
function buildKerbGeometry() {
  const P = [], CL = [];
  const RED = [0.55, 0.03, 0.04], WHT = [0.72, 0.72, 0.74];
  const pt = (idx, lat, h) => [LP[3 * idx] + LN[3 * idx] * lat, LP[3 * idx + 1] + h, LP[3 * idx + 2] + LN[3 * idx + 2] * lat];
  for (let i = 0; i < NL; i++) {
    if (Math.abs(LK[i]) < 0.011) continue;
    const i1 = (i + 1) % NL;
    const col = (i & 1) ? WHT : RED;
    for (const sd of [-1, 1]) {
      const A = pt(i, sd * 6.95, 0.03), B = pt(i, sd * 8.0, 0.03);
      const C1 = pt(i1, sd * 6.95, 0.03), D = pt(i1, sd * 8.0, 0.03);
      P.push(...A, ...B, ...C1, ...B, ...D, ...C1);
      for (let q = 0; q < 6; q++) CL.push(col[0], col[1], col[2]);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(P, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(CL, 3));
  g.computeVertexNormals();
  return g;
}

const ROAD_LATS = [-7, -5.25, -3.5, -1.75, 0, 1.75, 3.5, 5.25, 7];
const ROAD_PROFILE = ROAD_LATS.map(l => [l, 0.02, (l + 7) / 14]);
const POOL_PROFILE = ROAD_LATS.map(l => [l, 0.035, (l + 7) / 14]);

// Builds all trackside meshes. MAT supplies materials (created by the environment code).
function buildTrack(MAT) {
  const G = new THREE.Group();
  G.name = 'track';
  G.add(strip(ROAD_PROFILE, 0, L, NL, { uvScale: 14, mat: MAT.asphalt, recv: true }));
  G.add(strip(POOL_PROFILE, 0, L, NL, {
    uvScale: 14, mat: MAT.pool,
    col: (s, lat) => { const I = poolAt(s, lat); return [0.55 * I, 0.62 * I, 0.80 * I]; }
  }));
  G.add(new THREE.Mesh(buildKerbGeometry(), MAT.kerb));
  for (const sd of [-1, 1]) {
    G.add(strip([[sd * 7.0, 0.012, 0], [sd * 9.0, 0.012, 1]], 0, L, NL, { uvScale: 20, mat: MAT.runoff, recv: true }));
    G.add(strip([[sd * 6.55, 0.03, 0], [sd * 6.85, 0.03, 1]], 0, L, NL, { uvScale: 6, mat: MAT.line }));
    // steel barrier with capping rail
    G.add(strip([[sd * 9.0, 0, 0], [sd * 9.0, 0.75, 0.2], [sd * 9.25, 0.75, 0.45], [sd * 9.25, 0, 0.7]], 0, L, NL, { uvScale: 4, mat: MAT.barrier }));
    // catch fencing
    G.add(strip([[sd * 10.0, 0, 0], [sd * 10.0, 2.6, 1]], 0, L, NL, { uvScale: 3, mat: MAT.fence }));
  }
  // pit wall on the +Z side of the main straight
  G.add(strip([[11.0, 0, 0], [11.0, 1.2, 0.2], [11.6, 1.2, 0.5], [11.6, 0, 0.7]], -150, 120, 540, { uvScale: 4, mat: MAT.concrete }));
  // chequered start/finish line at s = 0
  G.add(strip([[-7, 0.045, 0], [7, 0.045, 1]], -0.6, 0.6, 1, { uvScale: 1.2, mat: MAT.checker }));
  // painted grid boxes (red on pole at s = -8, blue at s = -16)
  G.add(strip([[-3.5, 0.036, 0], [-1.5, 0.036, 1]], -9.5, -6.5, 2, { uvScale: 3, mat: MAT.gridBox }));
  G.add(strip([[1.5, 0.036, 0], [3.5, 0.036, 1]], -17.5, -14.5, 2, { uvScale: 3, mat: MAT.gridBox }));

  // start gantry across the road at s = 2, five start-light pods facing the grid (-X)
  const gant = new THREE.Group();
  gant.matrixAutoUpdate = false;
  gant.matrix.copy(trackFrame(2, 0));
  gant.matrixWorldNeedsUpdate = true;
  const addM = (geo, mat, x, y, z) => { const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.castShadow = true; gant.add(m); return m; };
  addM(new THREE.CylinderGeometry(0.22, 0.26, 7.2, 10), MAT.steel, 0, 3.6, -8.6);
  addM(new THREE.CylinderGeometry(0.22, 0.26, 7.2, 10), MAT.steel, 0, 3.6, 8.6);
  addM(new THREE.BoxGeometry(0.5, 0.5, 17.6), MAT.steel, 0, 7.3, 0);
  const lampGeo = new THREE.CircleGeometry(0.2, 18); lampGeo.rotateY(-Math.PI / 2);
  const lamps = [];
  for (let k = 0; k < 5; k++) {
    const z = -4 + 2 * k;
    addM(new THREE.BoxGeometry(0.5, 0.62, 0.62), MAT.steel, -0.45, 6.4, z);
    const lm = new THREE.MeshBasicMaterial({ color: sc(0x2a0306) });
    const disc = new THREE.Mesh(lampGeo, lm);
    disc.position.set(-0.72, 6.4, z);
    gant.add(disc);
    lamps.push(lm);
  }
  G.add(gant);
  G.userData.lamps = lamps;
  return G;
}

