// =====================================================================
// 2. Procedural canvas textures (detached canvases only)
// =====================================================================
function canvasTex(w, h, draw, srgb) {
  const cv = document.createElement('canvas');
  cv.width = w; cv.height = h;
  const g = cv.getContext('2d');
  draw(g, w, h);
  const tex = new THREE.CanvasTexture(cv);
  if (srgb) tex.encoding = THREE.sRGBEncoding;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 4;
  return tex;
}
const TEX = {};
function buildTextures() {
  TEX.asphalt = canvasTex(512, 512, (g, w, h) => {
    g.fillStyle = '#2b2f36'; g.fillRect(0, 0, w, h);
    for (let i = 0; i < 7000; i++) {
      const x = rng() * w, y = rng() * h, r = 0.6 + rng() * 1.8, c = 22 + Math.floor(rng() * 46);
      g.fillStyle = 'rgba(' + c + ',' + (c + 4) + ',' + (c + 10) + ',' + (0.35 + rng() * 0.45) + ')';
      g.fillRect(x, y, r, r);
    }
    for (let i = 0; i < 220; i++) {                      // wet darker patches
      const x = rng() * w, y = rng() * h, r = 8 + rng() * 26;
      const gr = g.createRadialGradient(x, y, 0, x, y, r);
      gr.addColorStop(0, 'rgba(10,12,16,0.35)'); gr.addColorStop(1, 'rgba(10,12,16,0)');
      g.fillStyle = gr; g.fillRect(x - r, y - r, 2 * r, 2 * r);
    }
  }, true);
  TEX.carbon = canvasTex(256, 256, (g, w, h) => {
    g.fillStyle = '#17191d'; g.fillRect(0, 0, w, h);
    for (let y = 0; y < h; y += 8) {
      for (let x = 0; x < w; x += 8) {
        const a = ((x >> 3) + (y >> 3)) & 1;
        g.fillStyle = a ? 'rgba(84,90,100,0.55)' : 'rgba(18,20,24,0.7)';
        g.fillRect(x, y, 8, 4);
        g.fillStyle = a ? 'rgba(30,32,38,0.6)' : 'rgba(96,102,112,0.35)';
        g.fillRect(x + 4, y + 4, 4, 4);
      }
    }
  }, true);
  const numberTex = (txt, fill) => canvasTex(512, 256, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    g.font = 'bold 200px Helvetica, Arial, sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.lineWidth = 14; g.strokeStyle = 'rgba(10,12,16,0.85)';
    g.strokeText(txt, w / 2, h / 2 + 6);
    g.fillStyle = fill; g.fillText(txt, w / 2, h / 2 + 6);
  }, true);
  TEX.num7 = numberTex('7', '#f4f6fa');
  TEX.num23 = numberTex('23', '#dfe4ec');
  TEX.fence = canvasTex(256, 256, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    g.strokeStyle = '#ffffff'; g.lineWidth = 5; g.lineCap = 'square';
    for (let k = -4; k <= 8; k++) {
      g.beginPath(); g.moveTo(k * 64, 0); g.lineTo(k * 64 + 256, 256); g.stroke();
      g.beginPath(); g.moveTo(k * 64 + 256, 0); g.lineTo(k * 64, 256); g.stroke();
    }
  }, false);
  TEX.checker = canvasTex(128, 32, (g, w, h) => {
    for (let y = 0; y < 2; y++) for (let x = 0; x < 8; x++) {
      g.fillStyle = ((x + y) & 1) ? '#f2f2f0' : '#101113';
      g.fillRect(x * 16, y * 16, 16, 16);
    }
  }, true);
  TEX.gridBox = canvasTex(128, 128, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    g.strokeStyle = '#eef0f4'; g.lineWidth = 9;
    g.strokeRect(6, 6, w - 12, h - 12);
  }, true);
  TEX.glow = canvasTex(256, 256, (g, w, h) => {
    const gr = g.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
    gr.addColorStop(0, 'rgba(255,255,255,1)');
    gr.addColorStop(0.25, 'rgba(255,255,255,0.45)');
    gr.addColorStop(0.6, 'rgba(255,255,255,0.12)');
    gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(0, 0, w, h);
  }, false);
  TEX.seats = canvasTex(256, 256, (g, w, h) => {
    g.fillStyle = '#1b1f27'; g.fillRect(0, 0, w, h);
    const cols = ['#7a1420', '#1f3f9a', '#c9ced6', '#2a2f38', '#8a6a1c', '#3a4a5a'];
    for (let i = 0; i < 1400; i++) {
      g.fillStyle = cols[Math.floor(rng() * cols.length)];
      g.globalAlpha = 0.35 + rng() * 0.4;
      g.fillRect(rng() * w, rng() * h, 4 + rng() * 3, 3 + rng() * 2);
    }
    g.globalAlpha = 1;
  }, true);
}

// =====================================================================
// 3. Night environment (PMREM from an in-memory scene), sky, fog, lights
// =====================================================================
let ENV = null;
function buildEnvironment(renderer) {
  const es = new THREE.Scene();
  es.add(new THREE.Mesh(new THREE.SphereGeometry(120, 24, 12),
    new THREE.MeshBasicMaterial({ color: sc(0x0a0d14), side: THREE.BackSide })));
  const panelMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(7.0, 7.2, 8.0), side: THREE.DoubleSide });
  for (let k = 0; k < 8; k++) {
    const a = k / 8 * TAU + 0.3;
    const p = new THREE.Mesh(new THREE.PlaneGeometry(16, 9), panelMat);
    p.position.set(Math.cos(a) * 70, 34, Math.sin(a) * 70);
    p.lookAt(0, 0, 0);
    es.add(p);
  }
  const pm = new THREE.PMREMGenerator(renderer);
  const rt = pm.fromScene(es, 0.04, 0.1, 300);
  pm.dispose();
  return rt.texture;
}

// Opaque procedural night sky: gradient, seeded stars, moon, warm city glow on one horizon.
const MOON_DIR = v3(0.42, 0.58, -0.70).normalize();
const SKY_MAT = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  depthTest: false,
  depthWrite: false,
  fog: false,
  uniforms: { uMoon: { value: MOON_DIR } },
  vertexShader: [
    'varying vec3 vDir;',
    'void main(){ vDir = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }'
  ].join('\n'),
  fragmentShader: [
    'varying vec3 vDir;',
    'uniform vec3 uMoon;',
    'float h2(vec3 p){ return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }',
    'void main(){',
    '  vec3 d = normalize(vDir);',
    '  float y = d.y;',
    '  vec3 top = vec3(0.004, 0.006, 0.013);',
    '  vec3 hor = vec3(0.060, 0.075, 0.100);',
    '  vec3 col = mix(hor, top, smoothstep(0.0, 0.55, y));',
    '  col = mix(col, vec3(0.012, 0.014, 0.018), smoothstep(0.0, -0.08, y));',
    '  float az = atan(d.z, d.x);',
    '  float glow = exp(-pow((az + 1.15) * 1.8, 2.0)) * exp(-y * y * 36.0);',
    '  col += vec3(0.20, 0.11, 0.05) * glow * 0.55;',
    '  vec3 q = floor(d * 240.0);',
    '  float star = step(0.9972, h2(q)) * smoothstep(0.03, 0.25, y);',
    '  col += vec3(0.75, 0.80, 0.95) * star * 0.6;',
    '  float md = dot(d, normalize(uMoon));',
    '  col += vec3(0.20, 0.24, 0.30) * smoothstep(0.9965, 0.9994, md) * 0.35;',
    '  col = mix(col, vec3(0.62, 0.66, 0.74), smoothstep(0.99940, 0.99962, md));',
    '  gl_FragColor = vec4(col, 1.0);',
    '}'
  ].join('\n')
});
const SKY_FOG = sc(0x161d2a);

function buildLights(scene) {
  scene.add(new THREE.AmbientLight(sc(0x2b3650), 0.08));
  const moon = new THREE.DirectionalLight(sc(0x7f9cff), 0.22);
  moon.position.set(-300, 420, 260);
  scene.add(moon);
  const spots = [];
  for (let k = 0; k < 2; k++) {
    const sl = new THREE.SpotLight(sc(0xeaf1ff), 1.8, 170, 0.62, 0.6, 1.0);
    sl.castShadow = true;
    sl.shadow.mapSize.width = 1024;
    sl.shadow.mapSize.height = 1024;
    sl.shadow.camera.near = 4;
    sl.shadow.camera.far = 180;
    sl.shadow.bias = -0.0008;
    scene.add(sl);
    scene.add(sl.target);
    spots.push(sl);
  }
  return spots;
}

// =====================================================================
// 4. Materials
// =====================================================================
const MAT = {};
function buildMaterials() {
  const envI = 0.85;
  MAT.asphalt = new THREE.MeshStandardMaterial({ color: sc(0x2a2e35), map: TEX.asphalt, roughness: 0.22, metalness: 0.0, envMap: ENV, envMapIntensity: envI, side: THREE.DoubleSide });
  MAT.pool = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  MAT.kerb = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.55, side: THREE.DoubleSide });
  MAT.runoff = new THREE.MeshStandardMaterial({ color: sc(0x1f232a), roughness: 0.7, side: THREE.DoubleSide });
  MAT.line = new THREE.MeshStandardMaterial({ color: sc(0xc9ced6), roughness: 0.4, side: THREE.DoubleSide });
  MAT.barrier = new THREE.MeshStandardMaterial({ color: sc(0x59606d), metalness: 0.6, roughness: 0.42, envMap: ENV, envMapIntensity: 0.8, side: THREE.DoubleSide });
  MAT.fence = new THREE.MeshStandardMaterial({ color: sc(0x9aa2ad), map: TEX.fence, alphaTest: 0.5, metalness: 0.6, roughness: 0.45, envMap: ENV, envMapIntensity: 0.7, side: THREE.DoubleSide });
  MAT.concrete = new THREE.MeshStandardMaterial({ color: sc(0x4a4f58), roughness: 0.8, side: THREE.DoubleSide });
  MAT.checker = new THREE.MeshStandardMaterial({ map: TEX.checker, roughness: 0.35, side: THREE.DoubleSide });
  MAT.gridBox = new THREE.MeshStandardMaterial({ map: TEX.gridBox, transparent: true, depthWrite: false, roughness: 0.5, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3 });
  MAT.steel = new THREE.MeshStandardMaterial({ color: sc(0x2f343c), metalness: 0.7, roughness: 0.4, envMap: ENV, envMapIntensity: 0.8 });
  MAT.seats = new THREE.MeshStandardMaterial({ map: TEX.seats, roughness: 0.8, side: THREE.DoubleSide });
  MAT.canopy = new THREE.MeshStandardMaterial({ color: sc(0x1e232b), roughness: 0.6, metalness: 0.3, side: THREE.DoubleSide });
  MAT.lightStrip = new THREE.MeshBasicMaterial({ color: new THREE.Color(1.5, 1.32, 1.0), side: THREE.DoubleSide });
  MAT.terrain = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, metalness: 0.0, side: THREE.DoubleSide });
  MAT.lampHead = new THREE.MeshBasicMaterial({ color: new THREE.Color(3.2, 3.0, 2.7), side: THREE.DoubleSide });
  MAT.cone = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
  MAT.lampGlow = new THREE.SpriteMaterial({ map: TEX.glow, color: sc(0xfff0d8), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
}

// Floodlight masts ~30 m tall, every ~70 m on alternating sides, each with a lamp head,
// a visible additive light cone aimed at the road and a glow bloom.
function buildMasts() {
  const G = new THREE.Group();
  const poleGeo = new THREE.CylinderGeometry(0.22, 0.34, 30, 8);
  const headGeo = new THREE.BoxGeometry(2.6, 1.3, 1.7);
  const panelGeo = new THREE.PlaneGeometry(2.3, 1.0);
  panelGeo.translate(0, 0, 0.86);
  for (let k = 0; k < NMAST; k++) {
    const s = MAST_S[k];
    const side = (k % 2 === 0) ? 1 : -1;
    const sp = trk(s);
    const nn = sp.n;
    const bx = sp.p[0] + nn[0] * side * 14.5, bz = sp.p[2] + nn[2] * side * 14.5, by = sp.p[1];
    const pole = new THREE.Mesh(poleGeo, MAT.steel);
    pole.position.set(bx, by + 15, bz);
    pole.castShadow = true;
    G.add(pole);
    const head = new THREE.Group();
    head.position.set(bx, by + 30.4, bz);
    const tgt = v3(sp.p[0] + nn[0] * side * 2.0, sp.p[1], sp.p[2] + nn[2] * side * 2.0);
    head.lookAt(tgt);
    const hb = new THREE.Mesh(headGeo, MAT.steel);
    hb.castShadow = true;
    head.add(hb);
    head.add(new THREE.Mesh(panelGeo, MAT.lampHead));
    const dist = head.position.distanceTo(tgt);
    const coneGeo = new THREE.ConeGeometry(9.5, dist, 24, 1, true);
    coneGeo.rotateX(-Math.PI / 2);
    coneGeo.translate(0, 0, dist / 2);
    const cp = coneGeo.attributes.position, cc = new Float32Array(cp.count * 3);
    for (let v = 0; v < cp.count; v++) {
      const t = clamp(cp.getZ(v) / dist, 0, 1);
      const I = lerpN(1.0, 0.04, t) * 0.16;
      cc[3 * v] = I * 0.85; cc[3 * v + 1] = I * 0.95; cc[3 * v + 2] = I * 1.15;
    }
    coneGeo.setAttribute('color', new THREE.BufferAttribute(cc, 3));
    head.add(new THREE.Mesh(coneGeo, MAT.cone));
    G.add(head);
    const glow = new THREE.Sprite(MAT.lampGlow);
    glow.position.set(bx, by + 30.4, bz);
    glow.scale.set(11, 11, 1);
    G.add(glow);
  }
  return G;
}

// Grandstand on the -Z side of the finish straight: stepped tiers, roof and emissive light strip
function buildGrandstand() {
  const G = new THREE.Group();
  const sA = L - 75, sB = L + 35, nSeg = 110;
  for (let t = 0; t < 6; t++) {
    const l0 = -(16 + 1.5 * t), l1 = -(16 + 1.5 * (t + 1));
    const hTop = 1.0 + 0.8 * t;
    G.add(strip([[l0, hTop, 0], [l1, hTop, 1]], sA, sB, nSeg, { uvScale: 6, mat: MAT.seats, recv: true }));
    G.add(strip([[l0, hTop - 0.8, 0], [l0, hTop, 1]], sA, sB, nSeg, { uvScale: 6, mat: MAT.canopy }));
  }
  G.add(strip([[-14.0, 9.8, 0], [-31.0, 11.2, 1]], sA, sB, nSeg, { uvScale: 20, mat: MAT.canopy }));
  G.add(strip([[-14.0, 9.6, 0], [-14.7, 9.6, 1]], sA, sB, nSeg, { uvScale: 20, mat: MAT.lightStrip }));
  return G;
}

