    new THREE.MeshBasicMaterial({ color: sc(0x0a0d14), side: THREE.BackSide })));
  const panelMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(7.0, 7.2, 8.0), side: THREE.DoubleSide });
  for (let k = 0; k < 8; k++) {
    const a = k / 8 * TAU + 0.3;
    const p = new THREE.Mesh(new THREE.PlaneGeometry(16, 9), panelMat);
    p.position.set(Math.cos(a) * 70, 34, Math.sin(a) * 70);
    p.lookAt(0, 0, 0);
    es.add(p);
  }
  const pm = new THREE.PMREMGenerator(renderer);
  const rt = pm.fromScene(es, 0.04, 0.1, 300);
