  strut([1.9, 0.2, 0], [2.3, 0.12, 0], 0.03, M.carbon);

  // ---- three-element front wing with endplates ----
  put(new THREE.BoxGeometry(0.42, 0.02, 1.9), M.carbon, 2.52, 0.11, 0);
  put(new THREE.BoxGeometry(0.36, 0.018, 1.86), M.white, 2.42, 0.19, 0, 0, 0, -0.08);
  put(new THREE.BoxGeometry(0.3, 0.016, 1.8), M.carbon, 2.34, 0.27, 0, 0, 0, -0.12);
  put(new THREE.BoxGeometry(0.52, 0.28, 0.02), M.paint, 2.5, 0.2, 0.95);
  put(new THREE.BoxGeometry(0.52, 0.28, 0.02), M.paint, 2.5, 0.2, -0.95);

  // ---- sculpted sidepods with undercut, radiator inlets, number decals ----
  for (const s of [-1, 1]) {
