// =====================================================================
// 5. Cars: code-generated F1-style single-seaters (red #7, blue #23)
//    Local frame: +X forward (nose), +Y up, +Z right. Reference = floor centre,
//    midway between the axles. Wheelbase 3.6 m, track-level floor at reference height.
// =====================================================================
function sculpt(geo, fn) {
  const p = geo.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const r = fn(p.getX(i), p.getY(i), p.getZ(i));
    p.setXYZ(i, r[0], r[1], r[2]);
  }
  p.needsUpdate = true;
  geo.computeVertexNormals();
  return geo;
}

function carMaterials(cfg) {
  const env = ENV;
  return {
    paint: new THREE.MeshPhysicalMaterial({ color: sc(cfg.paint), metalness: 0.35, roughness: 0.3, clearcoat: 1.0, clearcoatRoughness: 0.05, envMap: env, envMapIntensity: 1.1 }),
    accent: new THREE.MeshStandardMaterial({ color: sc(cfg.accent), metalness: 0.2, roughness: 0.35, envMap: env, envMapIntensity: 0.9 }),
    white: new THREE.MeshStandardMaterial({ color: sc(0xf1f3f6), roughness: 0.4, envMap: env, envMapIntensity: 0.8 }),
    silver: new THREE.MeshStandardMaterial({ color: sc(0xc7ced8), metalness: 1.0, roughness: 0.26, envMap: env, envMapIntensity: 1.0 }),
    carbon: new THREE.MeshStandardMaterial({ color: sc(0x40454e), map: TEX.carbon, metalness: 0.25, roughness: 0.4, envMap: env, envMapIntensity: 0.9 }),
    black: new THREE.MeshStandardMaterial({ color: sc(0x0d0e11), roughness: 0.85 }),
    tyre: new THREE.MeshStandardMaterial({ color: sc(0x0b0b0d), roughness: 0.8, side: THREE.DoubleSide }),
    visor: new THREE.MeshPhysicalMaterial({ color: sc(0x0a1222), metalness: 0.6, roughness: 0.06, envMap: env, envMapIntensity: 1.6 }),
    helmet: new THREE.MeshPhysicalMaterial({ color: sc(cfg.helmet), metalness: 0.2, roughness: 0.25, clearcoat: 1, clearcoatRoughness: 0.05, envMap: env, envMapIntensity: 1.0 }),
    disc: new THREE.MeshStandardMaterial({ color: sc(0x3b3f47), metalness: 0.7, roughness: 0.45, emissive: sc(0xff5a12), emissiveIntensity: 0 }),
    lamp: new THREE.MeshBasicMaterial({ color: sc(0x2a0000) }),
    decal: new THREE.MeshStandardMaterial({ map: cfg.numTex, transparent: true, depthWrite: false, roughness: 0.4, polygonOffset: true, polygonOffsetFactor: -4, polygonOffsetUnits: -4, envMap: env, envMapIntensity: 0.6 })
  };
}

function buildCar(cfg) {
  const M = carMaterials(cfg);
  const car = new THREE.Group();
  car.matrixAutoUpdate = false;
  const put = (geo, mat, x, y, z, rx, ry, rz) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    m.rotation.set(rx || 0, ry || 0, rz || 0);
    m.castShadow = true;
    car.add(m);
    return m;
  };
  // straight strut between two points (cylinder aligned a -> b)
  const strut = (a, b, r, mat) => {
    const dir = v3(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
    const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, dir.length(), 6), mat);
    m.position.set((a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2);
    m.quaternion.setFromUnitVectors(v3(0, 1, 0), dir.normalize());
    m.castShadow = true;
    car.add(m);
    return m;
  };

  // ---- floor, raised edges, rear diffuser ----
  put(sculpt(new THREE.BoxGeometry(4.1, 0.05, 1.2, 10, 1, 4).translate(-0.15, 0.085, 0),
    (x, y, z) => [x, y, z * (1 - 0.5 * clamp((x - 1.2) / 0.7, 0, 1))]), M.carbon, 0, 0, 0);
  put(new THREE.BoxGeometry(3.7, 0.07, 0.05), M.carbon, -0.2, 0.13, 0.6);
  put(new THREE.BoxGeometry(3.7, 0.07, 0.05), M.carbon, -0.2, 0.13, -0.6);
  put(new THREE.BoxGeometry(0.8, 0.3, 1.1), M.carbon, -2.05, 0.2, 0, 0, 0, -0.2);

  // ---- monocoque with open cockpit, halo, driver, steering wheel ----
  put(new THREE.BoxGeometry(0.9, 0.46, 0.5).translate(0, 0, 0), M.paint, -0.65, 0.33, 0);
  put(new THREE.BoxGeometry(0.8, 0.42, 0.46), M.paint, 1.0, 0.31, 0);
  put(new THREE.BoxGeometry(0.8, 0.14, 0.05), M.paint, 0.2, 0.47, 0.25);
  put(new THREE.BoxGeometry(0.8, 0.14, 0.05), M.paint, 0.2, 0.47, -0.25);
  put(new THREE.BoxGeometry(0.8, 0.04, 0.42), M.black, 0.2, 0.2, 0);
  put(new THREE.BoxGeometry(0.5, 0.2, 0.34), M.carbon, 0.0, 0.3, 0);
  put(new THREE.BoxGeometry(0.42, 0.3, 0.36), M.white, 0.0, 0.5, 0);
  const helmet = put(new THREE.SphereGeometry(0.13, 20, 14), M.helmet, 0.04, 0.66, 0);
  helmet.scale.set(1.0, 1.05, 0.95);
  put(new THREE.SphereGeometry(0.139, 18, 10, Math.PI - 0.9, 1.8, 1.0, 0.9), M.visor, 0.04, 0.66, 0);
  put(new THREE.BoxGeometry(0.1, 0.12, 0.24), M.black, 0.56, 0.42, 0, 0, 0, 0.15);
  const haloCurve = new THREE.CatmullRomCurve3([
    v3(0.62, 0.46, -0.25), v3(0.5, 0.7, -0.22), v3(0.22, 0.84, -0.14), v3(0.04, 0.87, 0),
    v3(0.22, 0.84, 0.14), v3(0.5, 0.7, 0.22), v3(0.62, 0.46, 0.25)]);
  put(new THREE.TubeGeometry(haloCurve, 40, 0.02, 8, false), M.carbon, 0, 0, 0);
  strut([0.62, 0.45, -0.25], [0.5, 0.7, -0.22], 0.018, M.carbon);
  strut([0.62, 0.45, 0.25], [0.5, 0.7, 0.22], 0.018, M.carbon);

  // ---- airbox and roll hoop ----
  put(sculpt(new THREE.BoxGeometry(0.7, 0.24, 0.44, 6, 3, 4).translate(-0.42, 0.83, 0),
    (x, y, z) => [x, y, z * (1 - 0.35 * clamp((y - 0.71) / 0.24, 0, 1))]), M.paint, 0, 0, 0);
  strut([-0.66, 0.46, -0.2], [-0.5, 0.9, 0], 0.03, M.carbon);
  strut([-0.66, 0.46, 0.2], [-0.5, 0.9, 0], 0.03, M.carbon);
  strut([-0.5, 0.9, -0.12], [-0.5, 0.9, 0.12], 0.025, M.carbon);

  // ---- slender nose with tapering tip and front pylon ----
  put(sculpt(new THREE.BoxGeometry(1.72, 0.36, 0.44, 12, 3, 3).translate(1.76, 0.26, 0),
    (x, y, z) => {
      const t = clamp((x - 0.9) / 1.72, 0, 1);
      return [x, 0.26 + (y - 0.26) * (1 - 0.62 * t), z * (1 - 0.7 * t)];
    }), M.paint, 0, 0, 0);
  strut([1.9, 0.2, 0], [2.3, 0.12, 0], 0.03, M.carbon);

  // ---- three-element front wing with endplates ----
  put(new THREE.BoxGeometry(0.42, 0.02, 1.9), M.carbon, 2.52, 0.11, 0);
  put(new THREE.BoxGeometry(0.36, 0.018, 1.86), M.white, 2.42, 0.19, 0, 0, 0, -0.08);
  put(new THREE.BoxGeometry(0.3, 0.016, 1.8), M.carbon, 2.34, 0.27, 0, 0, 0, -0.12);
  put(new THREE.BoxGeometry(0.52, 0.28, 0.02), M.paint, 2.5, 0.2, 0.95);
  put(new THREE.BoxGeometry(0.52, 0.28, 0.02), M.paint, 2.5, 0.2, -0.95);

  // ---- sculpted sidepods with undercut, radiator inlets, number decals ----
  for (const s of [-1, 1]) {
    put(sculpt(new THREE.BoxGeometry(1.9, 0.44, 0.52, 14, 3, 3).translate(-0.05, 0.3, s * 0.6), (x, y, z) => {
      const t = clamp((x + 1.0) / 1.9, 0, 1);
      const undercut = (y < 0.18 && t < 0.55) ? 1 : 0;
      return [x, 0.3 + (y - 0.3) * (0.85 + 0.15 * t), z - s * 0.12 * undercut];
    }), M.paint, 0, 0, 0);
    put(new THREE.BoxGeometry(0.3, 0.14, 0.08), M.black, 0.93, 0.5, s * 0.6);
    put(new THREE.PlaneGeometry(0.62, 0.36), M.decal, -0.1, 0.3, s * 0.875, 0, s < 0 ? Math.PI : 0, 0);
  }

  // ---- engine cover (tapering) and beam wing ----
  put(sculpt(new THREE.BoxGeometry(1.9, 0.26, 0.56, 10, 3, 4).translate(-1.15, 0.6, 0), (x, y, z) => {
    const t = clamp((-0.2 - x) / 1.9, 0, 1);
    return [x, 0.47 + (y - 0.47) * (1 - 0.35 * t), z * (1 - 0.35 * t)];
  }), M.paint, 0, 0, 0);
  put(new THREE.BoxGeometry(0.5, 0.03, 1.0), M.carbon, -1.62, 0.44, 0);
  put(new THREE.BoxGeometry(0.5, 0.09, 0.02), M.carbon, -1.62, 0.44, 0.5);
  put(new THREE.BoxGeometry(0.5, 0.09, 0.02), M.carbon, -1.62, 0.44, -0.5);

  // ---- rear crash structure with red rain light ----
  put(new THREE.BoxGeometry(0.42, 0.34, 0.34), M.paint, -2.42, 0.5, 0);
  put(new THREE.BoxGeometry(0.05, 0.07, 0.12), M.lamp, -2.65, 0.55, 0);

  // ---- two-element rear wing with louvred endplates and DRS flap ----
  put(new THREE.BoxGeometry(0.56, 0.03, 1.12), M.carbon, -2.45, 0.98, 0);
  const drsPivot = new THREE.Group();
  drsPivot.position.set(-2.2, 1.06, 0);
  car.add(drsPivot);
  const flap = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.03, 1.1), M.carbon);
  flap.position.set(-0.25, 0, 0);
  flap.castShadow = true;
  drsPivot.add(flap);
  for (const s of [-1, 1]) {
    put(new THREE.BoxGeometry(0.56, 0.5, 0.02), M.paint, -2.45, 0.9, s * 0.56);
    for (let k = 0; k < 3; k++) put(new THREE.BoxGeometry(0.3, 0.02, 0.01), M.black, -2.45, 0.78 + 0.1 * k, s * 0.575);
  }
  put(new THREE.BoxGeometry(0.1, 0.5, 0.1), M.carbon, -2.22, 0.62, 0);

  // ---- wing mirrors ----
  for (const s of [-1, 1]) {
    strut([0.5, 0.52, s * 0.42], [0.58, 0.7, s * 0.66], 0.012, M.carbon);
    put(new THREE.BoxGeometry(0.16, 0.08, 0.03), M.silver, 0.6, 0.72, s * 0.7, 0, s * 0.25, 0);
  }

  // ---- exposed suspension wishbones and push-rods (carbon) ----
  for (const s of [-1, 1]) {
    strut([1.2, 0.2, s * 0.2], [1.8, 0.36, s * 0.72], 0.018, M.carbon);
    strut([0.92, 0.22, s * 0.22], [1.8, 0.36, s * 0.72], 0.018, M.carbon);
    strut([1.18, 0.5, s * 0.22], [1.8, 0.56, s * 0.7], 0.016, M.carbon);
    strut([0.95, 0.5, s * 0.24], [1.8, 0.56, s * 0.7], 0.016, M.carbon);
    strut([1.8, 0.54, s * 0.7], [1.05, 0.56, s * 0.3], 0.012, M.carbon);
    strut([-1.22, 0.2, s * 0.25], [-1.8, 0.36, s * 0.74], 0.018, M.carbon);
    strut([-1.5, 0.22, s * 0.25], [-1.8, 0.36, s * 0.74], 0.018, M.carbon);
    strut([-1.25, 0.5, s * 0.26], [-1.8, 0.58, s * 0.7], 0.016, M.carbon);
    strut([-1.52, 0.5, s * 0.26], [-1.8, 0.58, s * 0.7], 0.016, M.carbon);
    strut([-1.8, 0.56, s * 0.68], [-1.15, 0.5, s * 0.3], 0.012, M.carbon);
  }

  // ---- four open wheels: tyre, coloured sidewall band, rim, brake disc, hub, five nuts ----
  const wheels = [];
  const buildWheel = (x, z, width, front) => {
    const wg = new THREE.Group();          // axle centre; steering rotates about Y
    const spin = new THREE.Group();        // rolls about Z (the axle)
    wg.position.set(x, 0.36, z);
    wg.add(spin);
    const s = z < 0 ? -1 : 1;
    const w = width;
    const wm = (geo, mat, px, py, pz) => { const m = new THREE.Mesh(geo, mat); m.position.set(px || 0, py || 0, pz || 0); m.castShadow = true; spin.add(m); return m; };
    const prof = [[0.215, -w / 2], [0.30, -w / 2], [0.335, -w / 2 + 0.015], [0.36, -w / 2 + 0.06],
                  [0.36, w / 2 - 0.06], [0.335, w / 2 - 0.015], [0.30, w / 2], [0.215, w / 2]]
                  .map(p => new THREE.Vector2(p[0], p[1]));
    const tyreGeo = new THREE.LatheGeometry(prof, 30);
    tyreGeo.rotateX(Math.PI / 2);
    wm(tyreGeo, M.tyre);
    wm(new THREE.RingGeometry(0.225, 0.30, 30), M.accent, 0, 0, s * (w / 2 + 0.004));
    wm(new THREE.RingGeometry(0.225, 0.30, 30), M.accent, 0, 0, -s * (w / 2 + 0.004));
    const rimGeo = new THREE.LatheGeometry([new THREE.Vector2(0.22, -0.09), new THREE.Vector2(0.31, -0.09),
                                            new THREE.Vector2(0.31, 0.09), new THREE.Vector2(0.22, 0.09)], 24);
    rimGeo.rotateX(Math.PI / 2);
    wm(rimGeo, M.silver);
    const discGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.035, 36); discGeo.rotateX(Math.PI / 2);
    wm(discGeo, M.disc);
    const hubGeo = new THREE.CylinderGeometry(0.07, 0.07, 0.16, 16); hubGeo.rotateX(Math.PI / 2);
    wm(hubGeo, M.silver);
    const nutGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.03, 8); nutGeo.rotateX(Math.PI / 2);
    for (let k = 0; k < 5; k++) {
      const a = k * TAU / 5 + 0.3;
      wm(nutGeo, M.silver, Math.cos(a) * 0.05, Math.sin(a) * 0.05, s * 0.085);
    }
    car.add(wg);
    wheels.push({ wg: wg, spin: spin, front: front, x: x, z: z, rolling: 1 });
  };
  buildWheel(1.8, 0.84, 0.31, true);
  buildWheel(1.8, -0.84, 0.31, true);
  buildWheel(-1.8, 0.82, 0.40, false);
  buildWheel(-1.8, -0.82, 0.40, false);

  return { group: car, wheels: wheels, drsPivot: drsPivot, rainMat: M.lamp, discMat: M.disc, cfg: cfg };
}

