  }
  put(new THREE.BoxGeometry(0.1, 0.5, 0.1), M.carbon, -2.22, 0.62, 0);

  // ---- wing mirrors ----
  for (const s of [-1, 1]) {
    strut([0.5, 0.52, s * 0.42], [0.58, 0.7, s * 0.66], 0.012, M.carbon);
    put(new THREE.BoxGeometry(0.16, 0.08, 0.03), M.silver, 0.6, 0.72, s * 0.7, 0, s * 0.25, 0);
  }

  // ---- exposed suspension wishbones and push-rods (carbon) ----
  for (const s of [-1, 1]) {
    strut([1.2, 0.2, s * 0.2], [1.8, 0.36, s * 0.72], 0.018, M.carbon);
    strut([0.92, 0.22, s * 0.22], [1.8, 0.36, s * 0.72], 0.018, M.carbon);
    strut([1.18, 0.5, s * 0.22], [1.8, 0.56, s * 0.7], 0.016, M.carbon);
    strut([0.95, 0.5, s * 0.24], [1.8, 0.56, s * 0.7], 0.016, M.carbon);
    strut([1.8, 0.54, s * 0.7], [1.05, 0.56, s * 0.3], 0.012, M.carbon);
    strut([-1.22, 0.2, s * 0.25], [-1.8, 0.36, s * 0.74], 0.018, M.carbon);
    strut([-1.5, 0.22, s * 0.25], [-1.8, 0.36, s * 0.74], 0.018, M.carbon);
    strut([-1.25, 0.5, s * 0.26], [-1.8, 0.58, s * 0.7], 0.016, M.carbon);
    strut([-1.52, 0.5, s * 0.26], [-1.8, 0.58, s * 0.7], 0.016, M.carbon);
    strut([-1.8, 0.56, s * 0.68], [-1.15, 0.5, s * 0.3], 0.012, M.carbon);
  }

  // ---- four open wheels: tyre, coloured sidewall band, rim, brake disc, hub, five nuts ----
  const wheels = [];
  const buildWheel = (x, z, width, front) => {
    const wg = new THREE.Group();          // axle centre; steering rotates about Y
    const spin = new THREE.Group();        // rolls about Z (the axle)
    wg.position.set(x, 0.36, z);
    wg.add(spin);
    const s = z < 0 ? -1 : 1;
    const w = width;
    const wm = (geo, mat, px, py, pz) => { const m = new THREE.Mesh(geo, mat); m.position.set(px || 0, py || 0, pz || 0); m.castShadow = true; spin.add(m); return m; };
    const prof = [[0.215, -w / 2], [0.30, -w / 2], [0.335, -w / 2 + 0.015], [0.36, -w / 2 + 0.06],
                  [0.36, w / 2 - 0.06], [0.335, w / 2 - 0.015], [0.30, w / 2], [0.215, w / 2]]
                  .map(p => new THREE.Vector2(p[0], p[1]));
    const tyreGeo = new THREE.LatheGeometry(prof, 30);
    tyreGeo.rotateX(Math.PI / 2);
    wm(tyreGeo, M.tyre);
    wm(new THREE.RingGeometry(0.225, 0.30, 30), M.accent, 0, 0, s * (w / 2 + 0.004));
    wm(new THREE.RingGeometry(0.225, 0.30, 30), M.accent, 0, 0, -s * (w / 2 + 0.004));
    const rimGeo = new THREE.LatheGeometry([new THREE.Vector2(0.22, -0.09), new THREE.Vector2(0.31, -0.09),
                                            new THREE.Vector2(0.31, 0.09), new THREE.Vector2(0.22, 0.09)], 24);
    rimGeo.rotateX(Math.PI / 2);
    wm(rimGeo, M.silver);
    const discGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.035, 36); discGeo.rotateX(Math.PI / 2);
    wm(discGeo, M.disc);
    const hubGeo = new THREE.CylinderGeometry(0.07, 0.07, 0.16, 16); hubGeo.rotateX(Math.PI / 2);
    wm(hubGeo, M.silver);
    const nutGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.03, 8); nutGeo.rotateX(Math.PI / 2);
    for (let k = 0; k < 5; k++) {
      const a = k * TAU / 5 + 0.3;
      wm(nutGeo, M.silver, Math.cos(a) * 0.05, Math.sin(a) * 0.05, s * 0.085);
    }
    car.add(wg);
    wheels.push({ wg: wg, spin: spin, front: front, x: x, z: z, rolling: 1 });
  };
  buildWheel(1.8, 0.84, 0.31, true);
  buildWheel(1.8, -0.84, 0.31, true);
  buildWheel(-1.8, 0.82, 0.40, false);
  buildWheel(-1.8, -0.82, 0.40, false);

  return { group: car, wheels: wheels, drsPivot: drsPivot, rainMat: M.lamp, discMat: M.disc, cfg: cfg };
}

// Two cars: red #7 (pole, left of centreline) and blue #23
const CAR_RED = buildCar({ paint: 0xc8102e, accent: 0xf1f3f6, helmet: 0xf1f3f6, numTex: null });
const CAR_BLUE = buildCar({ paint: 0x1546c8, accent: 0xc7ced8, helmet: 0x1546c8, numTex: null });

