// =====================================================================
// 6. Particles. Every emitter is precomputed once from the seeded PRNG and
//    the car table; each particle's state at simTime is then a closed-form
//    function of (simTime - emissionTime). Nothing accumulates per frame.
// =====================================================================
function newBank() {
  return { n: 0, t0: [], life: [], ox: [], oy: [], oz: [], vx: [], vy: [], vz: [], s0: [], s1: [], a0: [], cr: [], cg: [], cb: [], grav: [] };
}
function pushP(B, t0, life, o, v, s0, s1, a0, col, grav) {
  B.t0.push(t0); B.life.push(life);
  B.ox.push(o[0]); B.oy.push(o[1]); B.oz.push(o[2]);
  B.vx.push(v[0]); B.vy.push(v[1]); B.vz.push(v[2]);
  B.s0.push(s0); B.s1.push(s1); B.a0.push(a0);
  B.cr.push(col[0]); B.cg.push(col[1]); B.cb.push(col[2]);
  B.grav.push(grav);
  B.n++;
}
function freezeBank(B) {
  const o = { n: B.n };
  for (const k of ['t0', 'life', 'ox', 'oy', 'oz', 'vx', 'vy', 'vz', 's0', 's1', 'a0', 'cr', 'cg', 'cb', 'grav']) {
    o[k] = Float32Array.from(B[k]);
  }
  return o;
}
function mpt(M, x, y, z) {               // local -> world point through Matrix4 (column-major)
  const e = M.elements;
  return [e[0] * x + e[4] * y + e[8] * z + e[12], e[1] * x + e[5] * y + e[9] * z + e[13], e[2] * x + e[6] * y + e[10] * z + e[14]];
}
function vdir(dir, a) { return [dir[0] * a, dir[1] * a, dir[2] * a]; }
function vadd(a, b) { return [a[0] + b[0], a[1] + b[1], a[2] + b[2]]; }

const FLASH_T = [];          // camera-flash times on the grandstand (also drive shutter clicks)
let PART_SMOKE = null, PART_GLINT = null;   // frozen banks

function precomputeParticles(tFinBlue) {
  const S = newBank();      // smoke / spray / shimmer (normal blending)
  const G = newBank();      // sparks and flashes (additive)

  // spray plumes from the rear wheels once moving (both cars)
  for (let c = 0; c < 2; c++) {
    for (let te = 3.0; te < 36.4; te += 1 / 30) {
      const P = carPose(c, te);
      if (P.v < 2) continue;
      for (let q = 0; q < 2; q++) {
        const sd = rng() < 0.5 ? -1 : 1;
        const o = mpt(P.M, -1.8, 0.08, sd * 0.82);
        const fw = vdir(P.T, 0.55 * P.v), up = vdir(P.U, 1.5 + 2.5 * rng()), la = vdir(P.N, sd * (0.5 + 1.2 * rng()));
        const v = vadd(vadd(fw, up), la);
        pushP(S, te, 0.6 + 0.4 * rng(), o, v, 0.2, 0.7 + 0.4 * rng(), 0.55, [0.8, 0.88, 0.97], 9.8);
      }
    }
  }
  // launch tyre smoke and wet tyre mist from the rear wheels (t = 3.0 - 5.6)
  for (let c = 0; c < 2; c++) {
    for (let te = 3.0; te < 5.6; te += 1 / 30) {
      const P = carPose(c, te);
      for (let w = 0; w < 2; w++) for (let q = 0; q < 2; q++) {
        const sd = w ? 1 : -1;
        const o = mpt(P.M, -1.8, 0.12, sd * 0.82);
        const v = vadd(vadd(vdir(P.U, 0.8 + 1.2 * rng()), vdir(P.N, sd * (0.2 + 0.6 * rng()))), vdir(P.T, -0.15 * P.v));
        pushP(S, te, 1.5 + 0.7 * rng(), o, v, 0.5, 3.0, 0.3, [0.85, 0.86, 0.9], -0.6);
      }
    }
  }
  // heat shimmer rising behind each car on the grid (t = 0 - 3)
  for (let c = 0; c < 2; c++) {
    for (let te = 0.0; te < 3.0; te += 1 / 30) {
      const P = carPose(c, te);
      for (let q = 0; q < 2; q++) {
        const o = mpt(P.M, -2.5 + 0.3 * rng(), 0.45, rr(-0.15, 0.15));
        pushP(S, te, 1.2 + 0.6 * rng(), o, vdir(P.U, 0.6), 0.25, 1.1, 0.05, [0.72, 0.78, 0.86], -0.2);
      }
    }
  }
  // hairpin: puff from the red car's unloaded inside front tyre (t = 21.1 - 21.9)
  for (let te = 21.1; te < 21.9; te += 1 / 30) {
    const P = carPose(0, te);
    const sIn = P.k >= 0 ? 1 : -1;
    for (let q = 0; q < 2; q++) {
      const o = mpt(P.M, 1.8, 0.2, sIn * 0.84);
      const v = vadd(vdir(P.U, 0.9 + 0.6 * rng()), vdir(P.T, -0.25 * P.v * 0.2));
      pushP(S, te, 1.6 + 0.6 * rng(), o, v, 0.35, 2.2, 0.4, [0.82, 0.82, 0.84], -0.4);
    }
  }
  // skid-block sparks: above 200 km/h or braking hard (sampled on a 60 Hz grid)
  for (let c = 0; c < 2; c++) {
    for (let te = 7.0; te < 40; te += 1 / 60) {
      const P = carPose(c, te);
      if (!(P.v > 55.6 || P.a < -6)) continue;
      for (let q = 0; q < 2; q++) {
        const o = mpt(P.M, 0.1 + rr(-0.3, 0.3), 0.03, rr(-0.25, 0.25));
        const v = vadd(vadd(vdir(P.U, 3 + 4 * rng()), vdir(P.T, -(2 + 4 * rng()))), vdir(P.N, (rng() - 0.5) * 5));
        pushP(G, te, 0.22 + 0.25 * rng(), o, v, 0.07, 0.03, 1.0, [1.0, 0.55, 0.18], 9.8);
      }
    }
  }
  // finish: camera flashes across the grandstand (tFin onwards), plus an opening burst
  const addFlash = (te) => {
    const sF = rr(L - 70, L + 30), lat = -rr(17, 24), h = rr(3, 8);
    const p = trk(sF);
    const o = [p.p[0] + p.n[0] * lat, p.p[1] + h, p.p[2] + p.n[2] * lat];
    FLASH_T.push(te);
    pushP(G, te, rr(0.08, 0.16), o, [0, 0, 0], rr(1.2, 2.2), 0, 1.0, [1.0, 0.97, 0.86], 0);
    const last = G.s1.length - 1;
    G.s1[last] = G.s0[last];
  };
  for (let te = tFinBlue; te < 40; te += 0.05) { addFlash(te); addFlash(te); }
  for (let k = 0; k < 40; k++) addFlash(tFinBlue + rr(0, 0.35));

  FLASH_T.sort((a, b) => a - b);
  PART_SMOKE = freezeBank(S);
  PART_GLINT = freezeBank(G);
}

const PART_VS = [
  'attribute float aSize;',
  'attribute float aAlpha;',
  'attribute vec3 aColor;',
  'uniform float uScale;',
  'varying float vAlpha;',
  'varying vec3 vColor;',
  'void main(){',
  '  vAlpha = aAlpha; vColor = aColor;',
  '  vec4 mv = modelViewMatrix * vec4(position, 1.0);',
  '  gl_PointSize = clamp(aSize * uScale / max(-mv.z, 0.1), 0.0, 220.0);',
  '  gl_Position = projectionMatrix * mv;',
  '}'
].join('\n');
const PART_FS = [
  'uniform sampler2D uTex;',
  'varying float vAlpha;',
  'varying vec3 vColor;',
  'void main(){',
  '  vec4 t = texture2D(uTex, gl_PointCoord);',
  '  float a = t.a * vAlpha;',
  '  if (a < 0.004) discard;',
  '  gl_FragColor = vec4(vColor, a);',
  '}'
].join('\n');

function makeParticleSystem(B, blending, scene) {
  const n = B.n;
  const geo = new THREE.BufferGeometry();
  const pos = new Float32Array(n * 3), size = new Float32Array(n), alpha = new Float32Array(n), col = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { col[3 * i] = B.cr[i]; col[3 * i + 1] = B.cg[i]; col[3 * i + 2] = B.cb[i]; }
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(size, 1));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
  geo.setAttribute('aColor', new THREE.BufferAttribute(col, 3));
  const mat = new THREE.ShaderMaterial({
    uniforms: { uTex: { value: TEX.glow }, uScale: { value: 800 } },
    vertexShader: PART_VS, fragmentShader: PART_FS,
    transparent: true, depthWrite: false, blending: blending
  });
  const pts = new THREE.Points(geo, mat);
  pts.frustumCulled = false;
  scene.add(pts);
  return { geo: geo, mat: mat, B: B, pos: pos, size: size, alpha: alpha };
}

// Evaluate every live particle at simTime t (pure function of t)
function updateParticleSystem(sys, t) {
  const B = sys.B, pos = sys.pos, size = sys.size, alpha = sys.alpha;
  for (let i = 0; i < B.n; i++) {
    const a = t - B.t0[i];
