// =====================================================================
// 7. Pose, camera and visual state: every value is a pure function of simTime
// =====================================================================
const LAMP_RAIN_ON = new THREE.Color(2.4, 0.05, 0.04);
const LAMP_RAIN_OFF = sc(0x2a0000);
const LAMP_RED_ON = new THREE.Color(2.4, 0.12, 0.10);
const LAMP_GREEN_ON = new THREE.Color(0.25, 2.3, 0.45);
const LAMP_DARK = sc(0x2a0306);
const DISC_GLOW = sc(0xff5a12);
let TFIN_BLUE = 36.49, TFIN_RED = 36.54;

// Car pose at simTime t for which = 0 (red #7) or 1 (blue #23).
// M maps car-local (+X forward, +Y up, +Z right) to world, with the reference point at C(s)+d*n.
function carPose(which, t) {
  const kin = carKin(which, t);
  const k = trk(kin.s);
  const T = k.t, N = k.n;
  const U = [-N[2] * T[1], N[2] * T[0] - N[0] * T[2], N[0] * T[1]];   // n x T
  const ref = [k.p[0] + N[0] * kin.d, k.p[1] + N[1] * kin.d, k.p[2] + N[2] * kin.d];
  const pitch = clamp(0.0032 * kin.a, -0.045, 0.045);                  // nose up under acceleration
  const roll = -clamp(0.0005 * kin.v * kin.v * k.k, -0.04, 0.04);      // body leans outward in corners
  const steer = -clamp(Math.atan(3.6 * k.k), -0.32, 0.32);             // Ackermann-style front steer
  const B = new THREE.Matrix4().makeBasis(v3(T[0], T[1], T[2]), v3(U[0], U[1], U[2]), v3(N[0], N[1], N[2]));
  const M = new THREE.Matrix4().makeTranslation(ref[0], ref[1], ref[2]);
  M.multiply(B).multiply(new THREE.Matrix4().makeRotationZ(pitch)).multiply(new THREE.Matrix4().makeRotationX(roll));
  return { which: which, M: M, ref: ref, T: T, U: U, N: N, s: kin.s, v: kin.v, a: kin.a, d: kin.d, k: k.k, steer: steer, pitch: pitch, roll: roll };
}

// Brake-disc heat: peak braking over the last 1.5 s with a 0.6 s cooling constant (closed form)
