      V.harm[k].g.gain.setTargetAtTime(bal[k] * 0.055 * load, now, 0.02);
    }
    V.lp.frequency.setTargetAtTime((cockpit && c === 1) ? 900 : 900 + 3200 * load, now, 0.03);
    V.eg.gain.setTargetAtTime((cockpit && c === 1 ? 1.4 : 1.0) * 0.2, now, 0.03);
    V.nb.frequency.setTargetAtTime(f0 * 1.8, now, 0.03);
    V.ng.gain.setTargetAtTime(0.03 * load, now, 0.03);
    V.wo.frequency.setTargetAtTime(1400 + (rpm - 5000) * 0.25, now, 0.03);
    V.wg.gain.setTargetAtTime(0.008 * load * clamp((rpm - 4000) / 6000, 0, 1), now, 0.03);

