// =====================================================================
// 8. Audio (Web Audio, synthesized). Continuous voices are set every frame from
//    simTime; one-shots fire only when forward playback crosses their event time.
//    Audio only reads simulation state.
// =====================================================================
const AudioCtxCls = window.AudioContext || window.webkitAudioContext;
let actx = null, masterG = null, noiseBuf = null, AU = null;
const ONESHOTS = [];
let audioPrevT = 0;
const SPEED_OF_SOUND = 343;
const SHOT_EDGES = [5, 11, 15, 20, 24, 30, 34];

function shotIndex(t) { let k = 0; while (k < SHOT_EDGES.length && t >= SHOT_EDGES[k]) k++; return k; }

function setPosNode(node, x, y, z) {
  if (node.positionX) { node.positionX.value = x; node.positionY.value = y; node.positionZ.value = z; }
  else node.setPosition(x, y, z);
}
function setPanner() {
  const p = actx.createPanner();
  p.panningModel = 'equalpower';
  p.distanceModel = 'inverse';
  p.refDistance = 8;
  p.maxDistance = 3000;
  p.rolloffFactor = 1.1;
  return p;
}
function noiseSource() {
  const s = actx.createBufferSource();
  s.buffer = noiseBuf;
  s.loop = true;
  s.start();
  return s;
}
function biquad(type, f, q) {
  const b = actx.createBiquadFilter();
  b.type = type; b.frequency.value = f; b.Q.value = q;
  return b;
}
function gainNode(v) { const g = actx.createGain(); g.gain.value = v; return g; }

function buildAudioGraph() {
  const G = {};
  G.gridPan = setPanner();
  G.gridPan.connect(masterG);
  G.cars = [0, 1].map((c) => {
    const pan = setPanner();
    pan.connect(masterG);
    const lp = biquad('lowpass', 3000, 0.7);
    const eg = gainNode(0.2);
    lp.connect(eg); eg.connect(pan);
    const harm = [];
    for (let k = 0; k < 4; k++) {
      const o = actx.createOscillator();
      o.type = 'sawtooth'; o.frequency.value = 200;
      const g = gainNode(0);
      o.connect(g); g.connect(lp); o.start();
      harm.push({ o: o, g: g });
    }
    const ns = noiseSource();
    const nb = biquad('bandpass', 900, 1.2);
    const ng = gainNode(0);
    ns.connect(nb); nb.connect(ng); ng.connect(lp);
    const wo = actx.createOscillator(); wo.type = 'sine'; wo.frequency.value = 1500; wo.start();
    const wg = gainNode(0); wo.connect(wg); wg.connect(pan);
    // tyre hiss, wheelspin screech, wet squeal, spark crackle, brake-disc squeal
    const hissN = noiseSource(), hissF = biquad('bandpass', 2600, 0.8), hissG = gainNode(0);
    hissN.connect(hissF); hissF.connect(hissG); hissG.connect(pan);
    const scrN = noiseSource(), scrF = biquad('bandpass', 2400, 6), scrG = gainNode(0);
    scrN.connect(scrF); scrF.connect(scrG); scrG.connect(pan);
    const sqN = noiseSource(), sqF = biquad('bandpass', 1800, 4), sqG = gainNode(0);
    sqN.connect(sqF); sqF.connect(sqG); sqG.connect(pan);
    const spN = noiseSource(), spF = biquad('bandpass', 4500, 2), spG = gainNode(0);
    spN.connect(spF); spF.connect(spG); spG.connect(pan);
    const bo = actx.createOscillator(); bo.type = 'sine'; bo.frequency.value = 6400; bo.start();
    const bg = gainNode(0); bo.connect(bg); bg.connect(pan);
    return { pan: pan, lp: lp, eg: eg, harm: harm, ng: ng, nb: nb, wo: wo, wg: wg,
             hissG: hissG, scrF: scrF, scrG: scrG, sqG: sqG, spG: spG, bo: bo, bg: bg };
  });
  // grandstand crowd (positioned at the grandstand), roar, floodlight hum, breeze, cockpit wind
  G.crowdPan = setPanner(); G.crowdPan.connect(masterG);
  const cN = noiseSource(), cF = biquad('bandpass', 600, 0.7);
  G.crowdG = gainNode(0.02); cN.connect(cF); cF.connect(G.crowdG); G.crowdG.connect(G.crowdPan);
  const rN = noiseSource(), rF = biquad('bandpass', 1100, 0.6);
  G.roarG = gainNode(0); rN.connect(rF); rF.connect(G.roarG); G.roarG.connect(G.crowdPan);
  const hum1 = actx.createOscillator(); hum1.type = 'sine'; hum1.frequency.value = 100; hum1.start();
  const hum2 = actx.createOscillator(); hum2.type = 'sine'; hum2.frequency.value = 200; hum2.start();
  G.humG = gainNode(0.0035); hum1.connect(G.humG); hum2.connect(G.humG); G.humG.connect(masterG);
  const bN = noiseSource(), bF = biquad('lowpass', 380, 0.5);
  G.breezeG = gainNode(0.012); bN.connect(bF); bF.connect(G.breezeG); G.breezeG.connect(masterG);
  const wN = noiseSource(), wF = biquad('lowpass', 1300, 0.6);
  G.windG = gainNode(0); wN.connect(wF); wF.connect(G.windG); G.windG.connect(masterG);
  return G;
}

// Set the listener at the active camera; Doppler is computed from each car's velocity relative to it
function setListener(pos, look) {
  const l = actx.listener;
  let fx = look[0] - pos[0], fy = look[1] - pos[1], fz = look[2] - pos[2];
  const fl = Math.hypot(fx, fy, fz) || 1; fx /= fl; fy /= fl; fz /= fl;
  if (l.positionX) {
    l.positionX.value = pos[0]; l.positionY.value = pos[1]; l.positionZ.value = pos[2];
    l.forwardX.value = fx; l.forwardY.value = fy; l.forwardZ.value = fz;
    l.upX.value = 0; l.upY.value = 1; l.upZ.value = 0;
  } else {
    l.setPosition(pos[0], pos[1], pos[2]);
    l.setOrientation(fx, fy, fz, 0, 1, 0);
  }
}

// 8-speed audio-only gearbox: bands on speed, rpm sawtooth 5000-12000 inside each gear
const GEAR_EDGES = [0, 14, 22, 30, 38, 46, 54, 62, 80];
function gearOf(v) { let g = 0; while (g < 7 && v >= GEAR_EDGES[g + 1]) g++; return g; }
function rpmOf(v) {
  const g = gearOf(v), lo = GEAR_EDGES[g], hi = GEAR_EDGES[g + 1];
  return 5000 + 7000 * clamp((v - lo) / (hi - lo), 0, 1);
}
// Most recent gear change before t: age in seconds and direction
function shiftAge(which, t) {
  const g0 = gearOf(carKin(which, t).v);
  for (let j = 1; j <= 15; j++) {
    const tj = t - j * 0.02;
    if (tj < 0) break;
    const gj = gearOf(carKin(which, tj).v);
    if (gj !== g0) return { age: j * 0.02, up: g0 > gj };
  }
  return null;
}

// one-shot synthesized sounds
function playBeep(t0) {
  const o = actx.createOscillator(); o.type = 'sine'; o.frequency.value = 880;
  const g = gainNode(0);
  g.gain.setValueAtTime(0, t0); g.gain.linearRampToValueAtTime(0.16, t0 + 0.005);
  g.gain.setValueAtTime(0.16, t0 + 0.11); g.gain.linearRampToValueAtTime(0, t0 + 0.13);
  o.connect(g); g.connect(masterG); o.start(t0); o.stop(t0 + 0.14);
  ONESHOTS.push(o);
}
function playClick(t0, level, freq) {
  const n = actx.createBufferSource(); n.buffer = noiseBuf;
  const f = biquad('bandpass', freq, 1.4);
  const g = gainNode(0);
  g.gain.setValueAtTime(level, t0); g.gain.linearRampToValueAtTime(0, t0 + 0.03);
  n.connect(f); f.connect(g); g.connect(masterG);
  n.start(t0, 0.1, 0.05); n.stop(t0 + 0.05);
  ONESHOTS.push(n);
}
function fireEvent(kind) {
  if (!actx || !AU) return;
  const now = actx.currentTime + 0.005;
  if (kind === 'beep') playBeep(now);
  else if (kind === 'drsOpen') playClick(now, 0.5, 3000);
  else if (kind === 'drsClose') playClick(now, 0.22, 2200);
  else if (kind === 'shutter') playClick(now, 0.12, 4200);
}
// Event times on the timeline (forward crossings only)
function audioEvents() {
  const ev = [];
  for (const b of [0.5, 1.0, 1.5, 2.0, 2.5]) ev.push({ t: b, k: 'beep' });
  ev.push({ t: 33.5, k: 'drsOpen' });
  ev.push({ t: TFIN_BLUE, k: 'drsClose' });
  for (const f of FLASH_T) ev.push({ t: f, k: 'shutter' });
  return ev;
}
let AUDIO_EVENTS = [];

function stopOneShots() {
  while (ONESHOTS.length) {
    const n = ONESHOTS.pop();
    try { n.stop(); } catch (e) { /* already ended */ }
  }
}

// Called once per frame. `playing` = state is PLAYING. `t` = simTime, `prev` = previous frame's simTime.
function updateAudio(t, playing, camPos, camLook) {
  if (!actx || !AU) return;
  const now = actx.currentTime;
  masterG.gain.setTargetAtTime(playing ? 0.8 : 0.0, now, playing ? 0.02 : 0.008);
  if (!playing) { stopOneShots(); audioPrevT = t; return; }

  setListener(camPos, camLook);
  const shot = shotIndex(t);
  const cockpit = shot === 3;
  const cars = [CAR_R, CAR_B];
  for (let c = 0; c < 2; c++) {
    const P = carPose(c, t);
    const kin = carKin(c, t);
    const V = AU.cars[c];
    // Doppler: ratio from radial velocity of the car relative to the listener
    const rel = [P.ref[0] - camPos[0], P.ref[1] - camPos[1], P.ref[2] - camPos[2]];
    const dist = Math.hypot(rel[0], rel[1], rel[2]) || 1;
    const vr = (P.T[0] * kin.v * rel[0] + P.T[1] * kin.v * rel[1] + P.T[2] * kin.v * rel[2]) / dist;
    const dop = clamp(SPEED_OF_SOUND / (SPEED_OF_SOUND + vr), 0.6, 1.8);
    setPosNode(V.pan, P.ref[0], P.ref[1] + 0.4, P.ref[2]);

    // engine: firing frequency = rpm / 20 for a V6 four-stroke
    let rpm, burble = 1;
    if (t < 3.0) {
      rpm = 2900 + 6100 * smoothstep(2.5, 3.0, t);                              // idle, revs with light five
      burble = 1 + 0.18 * Math.sin(TAU * 7.3 * t) * Math.sin(TAU * 2.1 * t) + 0.05 * Math.sin(TAU * 13.7 * t);
    } else {
      rpm = rpmOf(kin.v);
      const sh = shiftAge(c, t);
      if (sh) {
        if (sh.up) burble *= 1 - 0.09 * Math.exp(-sh.age / 0.12);            // pitch drop + dip on upshift
        else rpm *= 1 + 0.06 * Math.exp(-sh.age / 0.1);                       // blip on downshift
      }
    }
    const load = clamp(0.4 + kin.a / 12, 0.25, 1.0);                          // brighter under acceleration
    const f0 = (rpm / 20) * burble * dop;
    const bal = c === 0 ? [1.0, 0.42, 0.22, 0.10] : [0.82, 0.62, 0.38, 0.20];  // slightly different harmonic balance
    for (let k = 0; k < 4; k++) {
      V.harm[k].o.frequency.setTargetAtTime(f0 * (k + 1), now, 0.01);
      V.harm[k].g.gain.setTargetAtTime(bal[k] * 0.055 * load, now, 0.02);
    }
    V.lp.frequency.setTargetAtTime((cockpit && c === 1) ? 900 : 900 + 3200 * load, now, 0.03);
    V.eg.gain.setTargetAtTime((cockpit && c === 1 ? 1.4 : 1.0) * 0.2, now, 0.03);
    V.nb.frequency.setTargetAtTime(f0 * 1.8, now, 0.03);
    V.ng.gain.setTargetAtTime(0.03 * load, now, 0.03);
    V.wo.frequency.setTargetAtTime(1400 + (rpm - 5000) * 0.25, now, 0.03);
    V.wg.gain.setTargetAtTime(0.008 * load * clamp((rpm - 4000) / 6000, 0, 1), now, 0.03);

    // tyres, slides and sparks
    const lat = kin.v * kin.v * Math.abs(P.k);
    const hiss = (t >= 5 ? 0.010 + 0.035 * clamp(kin.v / 70, 0, 1) : 0);
    V.hissG.gain.setTargetAtTime(hiss, now, 0.05);
    const launch = (t >= 3 && t <= 5) ? Math.sin(Math.PI * (t - 3) / 2) : 0;
    V.scrF.frequency.setTargetAtTime(2400 + 300 * Math.sin(TAU * 9 * t), now, 0.02);
    V.scrG.gain.setTargetAtTime(0.045 * launch, now, 0.02);
    const sq = 0.5 * clamp((-kin.a - 6) / 12, 0, 1) + 0.5 * clamp(lat / 25, 0, 1);
    V.sqG.gain.setTargetAtTime(0.035 * sq * (t >= 5 ? 1 : 0), now, 0.04);
    const sparking = (kin.v > 55.6 || kin.a < -6) ? 1 : 0;
    V.spG.gain.setTargetAtTime(0.03 * sparking, now, 0.03);
    V.bg.gain.setTargetAtTime(0.010 * clamp((-kin.a - 15) / 10, 0, 1), now, 0.05);
  }
  // grandstand: murmur swells from 33 s, roar at the finish, decays over ~2 s
  const roar = t >= TFIN_BLUE ? 0.22 * Math.exp(-(t - TFIN_BLUE) / 2.0) : 0;
  AU.crowdG.gain.setTargetAtTime(0.018 + 0.05 * smoothstep(33, 35, t) + roar * 0.4, now, 0.05);
  AU.roarG.gain.setTargetAtTime(roar, now, 0.05);
  setPosNode(AU.crowdPan, GRANDSTAND_POS[0], GRANDSTAND_POS[1], GRANDSTAND_POS[2]);
  // cockpit wind roar only in shot 4 (blue onboard)
  AU.windG.gain.setTargetAtTime(cockpit ? 0.09 * clamp(kin.v / 70, 0, 1) : 0, now, 0.05);
}

