// =====================================================================
// 9. Bootstrap, playback state machine, dock controls, resize, frame loop
// =====================================================================
let renderer = null, scene = null, camera = null, SKY = null, SPOTS = [];
let CAR_R = null, CAR_B = null, TRACK_LAMPS = [], PSYS_SMOKE = null, PSYS_GLINT = null;
let GRANDSTAND_POS = [0, 0, 0];

const ST = { COUNTDOWN: 'COUNTDOWN', PLAYING: 'PLAYING', PAUSED: 'PAUSED', REFIRE_HOLD: 'REFIRE_HOLD', ENDED: 'ENDED' };
let state = ST.COUNTDOWN;
let simTime = 0;
let playbackSpeed = 1.0;
let countdownElapsed = 0;
let holdElapsed = 0;
let lastFrameMs = null;
let started = false;
const EL = {};

function crossTime(which, sTarget) {          // bisection on the monotone s(t) table
  let lo = 30, hi = 40;
  for (let i = 0; i < 60; i++) {
    const m = 0.5 * (lo + hi);
    if (carKin(which, m).s < sTarget) lo = m; else hi = m;
  }
  return 0.5 * (lo + hi);
}

function setIcons(playingIcon) {
  EL.iconPause.style.display = playingIcon ? '' : 'none';
  EL.iconPlay.style.display = playingIcon ? 'none' : '';
  EL.toggle.setAttribute('aria-label', playingIcon ? 'Pause' : 'Play');
}
function showCountdown(text) {
  EL.countdown.style.display = 'block';
  EL.countdown.textContent = text;
}
function hideCountdown() {
  EL.countdown.style.display = 'none';
  EL.countdown.textContent = '';
}
function setState(next) {
  state = next;
  setIcons(next === ST.PLAYING || next === ST.COUNTDOWN || next === ST.REFIRE_HOLD);
}
function fireEventsBetween(a, b) {
  if (!(b > a) || b - a > 0.5) return;        // ignore discontinuities
  for (let i = 0; i < AUDIO_EVENTS.length; i++) {
    const e = AUDIO_EVENTS[i];
    if (e.t > a && e.t <= b) fireEvent(e.k);
  }
}

function frame(nowMs) {
  const rawDt = lastFrameMs === null ? 0 : (nowMs - lastFrameMs) / 1000;
  lastFrameMs = nowMs;
  const dt = Math.min(Math.max(rawDt, 0), 0.1);
  if (!started) {
    started = true;                             // first rAF after the resting scene: COUNTDOWN begins
    state = ST.COUNTDOWN;
    countdownElapsed = 0;
    showCountdown('3');
  }
  if (state === ST.COUNTDOWN) {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) {
      hideCountdown();
      setState(ST.PLAYING);
    } else {
      const txt = countdownElapsed < 1.0 ? '3' : (countdownElapsed < 2.0 ? '2' : '1');
      if (EL.countdown.textContent !== txt) EL.countdown.textContent = txt;
    }
  } else if (state === ST.REFIRE_HOLD) {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) setState(ST.PLAYING);
  } else if (state === ST.PLAYING) {
    const before = simTime;
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    fireEventsBetween(before, simTime);
    EL.scrub.value = simTime.toFixed(3);
    if (simTime >= DURATION) {
      simTime = DURATION;
      EL.scrub.value = DURATION.toFixed(3);
      setState(ST.ENDED);
    }
  }
  renderAt(simTime);
  updateAudio(simTime, state === ST.PLAYING, CAMERA_EYE.p, CAMERA_EYE.l);
  requestAnimationFrame(frame);
}

function wireControls() {
  EL.toggle.addEventListener('click', () => {
    switch (state) {
      case ST.PLAYING:
        setState(ST.PAUSED);
        break;
      case ST.COUNTDOWN:
      case ST.REFIRE_HOLD:
        hideCountdown();
        simTime = 0;
        EL.scrub.value = '0';
        renderAt(0);
        setState(ST.PAUSED);
        break;
      case ST.PAUSED:
        setState(ST.PLAYING);
        break;
      case ST.ENDED:
        simTime = 0;
        EL.scrub.value = '0';
        hideCountdown();
        setState(ST.PLAYING);
        break;
    }
  });
  EL.refire.addEventListener('click', () => {
    hideCountdown();
    countdownElapsed = 0;
    holdElapsed = 0;
    simTime = 0;
    EL.scrub.value = '0';
    renderAt(0);
    setState(ST.REFIRE_HOLD);
  });
  EL.pills.forEach((pill) => {
    pill.addEventListener('click', () => {
      playbackSpeed = parseFloat(pill.getAttribute('data-speed'));
      EL.pills.forEach((q) => {
        const on = q === pill;
        q.classList.toggle('is-active', on);
        q.setAttribute('aria-checked', on ? 'true' : 'false');
      });
    });
  });
  EL.scrub.addEventListener('input', () => {
    if (state === ST.COUNTDOWN || state === ST.REFIRE_HOLD) hideCountdown();
    simTime = clamp(parseFloat(EL.scrub.value), 0, DURATION);
    renderAt(simTime);
    setState(ST.PAUSED);
  });
  const resumeAudio = () => { if (actx && actx.state !== 'running') actx.resume(); };
  document.addEventListener('pointerdown', resumeAudio);
  document.addEventListener('keydown', resumeAudio);
  window.addEventListener('resize', () => {
    const w = window.innerWidth, h = window.innerHeight;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  });
}

function bootstrap() {
  EL.countdown = document.getElementById('countdown');
  EL.toggle = document.getElementById('btn-toggle');
  EL.iconPause = document.getElementById('icon-pause');
  EL.iconPlay = document.getElementById('icon-play');
  EL.refire = document.getElementById('btn-refire');
  EL.scrub = document.getElementById('scrubber');
  EL.pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
  hideCountdown();

  renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('stage'), antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 0.95;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFShadowMap;

  scene = new THREE.Scene();
  camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 3000);

  audioInit();
  buildTextures();
  ENV = buildEnvironment(renderer);
  buildMaterials();
  setupFog(scene);
  SPOTS = buildLights(scene);

  SKY = new THREE.Mesh(new THREE.SphereGeometry(2400, 32, 16), SKY_MAT);
  SKY.renderOrder = -10;
  SKY.frustumCulled = false;
  scene.add(SKY);

  const trackG = buildTrack(MAT);
