  const start = open + marker.length;
  const end = text.lastIndexOf('</script>');
  const body = text.substring(start, end);
  try {
    new Function(body);
    return 'SYNTAX OK, script chars=' + body.length;
  } catch (e) {
    return 'SYNTAX ERROR: ' + String(e);
  }
}

