(function () {
  var out = [];
  var t0 = Date.now();
  out.push('three=' + THREE.REVISION);
  out.push('L=' + L.toFixed(4) + ' NL=' + NL + ' DS=' + DS.toFixed(4));
  function crossTime(which, sT) {
    var lo = 30, hi = 40;
    for (var i = 0; i < 60; i++) { var m = 0.5 * (lo + hi); if (carKin(which, m).s < sT) lo = m; else hi = m; }
    return 0.5 * (lo + hi);
  }
  TFIN_BLUE = crossTime(1, L); TFIN_RED = crossTime(0, L);
  out.push('tFinBlue=' + TFIN_BLUE.toFixed(3) + ' tFinRed=' + TFIN_RED.toFixed(3));
  // level point (sR == sB)
  var lo = 30, hi = 40;
  for (var i = 0; i < 60; i++) { var m = 0.5 * (lo + hi); if (carKin(1, m).s < carKin(0, m).s) lo = m; else hi = m; }
  out.push('levelTime=' + (0.5 * (lo + hi)).toFixed(3));
  [0, 4, 5, 7, 20, 34, 36, 40].forEach(function (t) {
    var r = carKin(0, t), b = carKin(1, t);
    out.push('t=' + t + ' R(s=' + r.s.toFixed(2) + ',d=' + r.d.toFixed(2) + ',v=' + r.v.toFixed(2) + ',a=' + r.a.toFixed(2) +
      ') B(s=' + b.s.toFixed(2) + ',d=' + b.d.toFixed(2) + ',v=' + b.v.toFixed(2) + ',a=' + b.a.toFixed(2) + ')');
  });
  var c0 = C(0), n0 = NN(0), cl = C(L - 0.01);
  out.push('C(0)=' + c0.map(function (x) { return x.toFixed(3); }).join(',') + ' n(0)=' + n0.map(function (x) { return x.toFixed(3); }).join(','));
  out.push('C(L-0.01)=' + cl.map(function (x) { return x.toFixed(3); }).join(','));
  var pr0 = carPose(0, 0), pb0 = carPose(1, 0);
  out.push('redRef(t0)=' + pr0.ref.map(function (x) { return x.toFixed(3); }).join(',') + ' blueRef=' + pb0.ref.map(function (x) { return x.toFixed(3); }).join(','));
  // orthonormality of the car frame along the lap
  var worst = 0;
  for (var ss = 0; ss < L; ss += 37.3) {
    var k = trk(ss);
    var d1 = k.t[0] * k.n[0] + k.t[2] * k.n[2];
    var U = [-k.n[2] * k.t[1], k.n[2] * k.t[0] - k.n[0] * k.t[2], k.n[0] * k.t[1]];
    var d2 = U[0] * k.t[0] + U[1] * k.t[1] + U[2] * k.t[2];
    var d3 = U[0] * k.n[0] + U[2] * k.n[2];
    worst = Math.max(worst, Math.abs(d1), Math.abs(d2), Math.abs(d3));
  }
  out.push('frame orthogonality worst=' + worst.toExponential(2));
  // gradient / curvature sanity
  var kmax = 0, kmin = 0; for (var q = 0; q < NL; q++) { kmax = Math.max(kmax, LK[q]); kmin = Math.min(kmin, LK[q]); }
  out.push('curvature range=[' + kmin.toFixed(4) + ',' + kmax.toFixed(4) + ']');
  // pitch-check on lap ends
  out.push('yRange=[' + Math.min.apply(null, Array.prototype.filter.call(LP, function (v, i) { return i % 3 === 1; })).toFixed(2) + ',' +
    Math.max.apply(null, Array.prototype.filter.call(LP, function (v, i) { return i % 3 === 1; })).toFixed(2) + ']');

