  out.push('particles smoke=' + PART_SMOKE.n + ' glint=' + PART_GLINT.n + ' flashes=' + FLASH_T.length + ' first=' + FLASH_T[0].toFixed(3) + ' ms=' + (Date.now() - tb));
  PSYS_SMOKE = makeParticleSystem(PART_SMOKE, THREE.NormalBlending, { add: function () {} });
  PSYS_GLINT = makeParticleSystem(PART_GLINT, THREE.AdditiveBlending, { add: function () {} });
  AUDIO_EVENTS = audioEvents();
  out.push('audio events=' + AUDIO_EVENTS.length);

  // ---- renderAt with a stub renderer ----
  renderer = { domElement: { height: 1080 }, render: function () {} };
  camera = new THREE.PerspectiveCamera(35, 16 / 9, 0.1, 3000);
  scene = new THREE.Scene();
  SKY = new THREE.Mesh(new THREE.SphereGeometry(2400, 8, 6), SKY_MAT);
  SPOTS = [new THREE.SpotLight(), new THREE.SpotLight()];
  SPOTS.forEach(function (s) { s.target = new THREE.Object3D(); });
  var times = [0, 0.5, 1.5, 2.5, 3.0, 4.0, 6.0, 9.0, 12.0, 16.0, 18.0, 22.0, 26.0, 31.0, 33.0, 33.6, 35.0, 36.5, 38.0, 40];
  var rt = Date.now();
  var worstMs = 0;
  times.forEach(function (t) {
    var a = Date.now();
    renderAt(t);
    worstMs = Math.max(worstMs, Date.now() - a);
    var sh = CAMERA_EYE;
    out.push('t=' + t + ' shot p=' + sh.p.map(function (x) { return x.toFixed(1); }).join(',') + ' l=' + sh.l.map(function (x) { return x.toFixed(1); }).join(',') + ' fov=' + sh.fov +
      ' drs=' + CAR_B.drsPivot.rotation.z.toFixed(3) + ' steerR=' + CAR_R.wheels[0].wg.rotation.y.toFixed(3) + ' rainMat=' + CAR_R.rainMat.color.r.toFixed(2) +
      ' disc=' + CAR_B.discMat.emissiveIntensity.toFixed(3));
  });
  out.push('renderAt total ms=' + (Date.now() - rt) + ' worst=' + worstMs);
  out.push('gantry lamp colours at t=2.6/3.1/37: ' + (setGantry(2.6), TRACK_LAMPS[0].color.r.toFixed(2) + '/' + TRACK_LAMPS[4].color.r.toFixed(2)) +
    ' ' + (setGantry(3.1), TRACK_LAMPS[0].color.r.toFixed(2)) + ' ' + (setGantry(37.0), TRACK_LAMPS[0].color.g.toFixed(2)));
  // particle update at a few times
  updateParticleSystem(PSYS_SMOKE, 4.0); updateParticleSystem(PSYS_GLINT, 36.6);
  var live = 0; for (var i2 = 0; i2 < PSYS_GLINT.size.length; i2++) if (PSYS_GLINT.size[i2] > 0) live++;
  out.push('live flashes at 36.6=' + live);
  out.push('total ms=' + (Date.now() - t0));
  return out.join('\n');
})();

