  AUDIO_EVENTS = audioEvents();

  audioInit();
  out.push('actx=' + (actx ? 'yes' : 'no') + ' AU=' + (AU ? 'yes' : 'no') + ' noiseBuf=' + (noiseBuf ? 'yes' : 'no'));
