  for (var t = 0; t <= 40.0001; t += 0.25) {
    try {
      renderAt(t);
      updateAudio(t, true, CAMERA_EYE.p, CAMERA_EYE.l);
      n++;
    } catch (e) { errs.push('playing t=' + t + ': ' + e + ' ' + (e.stack || '')); if (errs.length > 3) break; }
  }
  for (var t2 = 0; t2 <= 40; t2 += 1) {
    try { renderAt(t2); updateAudio(t2, false, CAMERA_EYE.p, CAMERA_EYE.l); n++; }
    catch (e) { errs.push('paused t=' + t2 + ': ' + e + ' ' + (e.stack || '')); if (errs.length > 3) break; }
  }
  var fired = 0;
  AUDIO_EVENTS.forEach(function (ev) {
    try { fireEvent(ev.k); fired++; } catch (e) { errs.push('fire ' + ev.k + ': ' + e); }
